data.query:
query Count($where: CountWhereInput, $orderBy: [CountOrderByInput!], $first: Int, $after: String) {
  count(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        number
        blind
        externalId
        scheduledStartAt
        actualStartAt
        completedAt
        customData
        integrationData
        countStatusId
        countParameters{
          edges{
            node{
              productId
              productCategoryId
              storageUnitId
              storageZoneId
              areaId         
            }
          }
        }
      }
    }
  }
}

query Inventory($where: InventoryWhereInput, $orderBy: [InventoryOrderByInput!], $first: Int, $after: String) {
  inventory(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    total
    pageInfo{ hasNextPage endCursor }
    edges {
      cursor
      node {
        productId
        product{
          code
        }
        storageUnitId
        quantity{
          _aggregate{
            value{ sum }
          }
        }
        grossWeight{
          _aggregate{
            value{ sum }
          }
        }
      }
    }
  }
}

data.responseTransform:
{
  "error": true,
  "message": "The count is not in a New status."
}

